head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt76101";
scwin.attachFileNum = 1;
scwin.obj = undefined;
scwin.frameId = undefined;
scwin.frame = undefined;
scwin.deleteFileArray = undefined;
scwin.deleteFileNameArray = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("sysDate")) { pc.set("sysDate", $c.date.getServerDateTime("yyyy-MM-dd")); }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — noticeDetail

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_contnMaindocContn", attr: "label", fn: function () { return String(dma_noticeDetail.get("contnMaindocContn")); } },
        { childId: "txa_miscContn", attr: "label", fn: function () { return String(dma_noticeDetail.get("miscContn")); } },
        { childId: "txa_remk", attr: "label", fn: function () { return String(dma_noticeDetail.get("remk")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "ipt_wrtDd_2", fn: function(){ return (((String(((dma_pageContext.get("noticeDetail") ?? "")) == null ? '' : ((dma_pageContext.get("noticeDetail") ?? ""))).length === 0))); } }, { id: "c_otherwise_131", fn: function(){ return (!((((String(((dma_pageContext.get("noticeDetail") ?? "")) == null ? '' : ((dma_pageContext.get("noticeDetail") ?? ""))).length === 0))))); } }, { id: "img_156", fn: function(){ return (!(String(((dma_pageContext.get("noticeDetail") ?? "")) == null ? '' : ((dma_pageContext.get("noticeDetail") ?? ""))).length === 0)); } }, { id: "txt_text157", fn: function(){ return (!(String(((dma_pageContext.get("noticeDetail") ?? "")) == null ? '' : ((dma_pageContext.get("noticeDetail") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_message", fn: function () { return String(String((dma_pageContext.get("message") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        if ($c.util.getComponent('dma_CopyReq').get('mode') === "create") {
            scwin.changeSysTpCd("2");
        }
        if ($c.util.getComponent('dma_CopyReq').get('mode') === "update") {
            $("#slc_notiObjSysTpCd option").attr('disabled', true);
            scwin.changeSysTpCd($c.util.getComponent('slc_notiObjSysTpCd').getValue());
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt76101.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 키 updatenotice 를 쓰는 tx 가 2개다(tx_fn_Copy, tx_fn_Update)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_copyForm = { action: "", method: 'post', target: '' };

scwin.form_editForm = { action: "", method: 'post', target: '' };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt76101' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt76101' }); }

try { scwin.frame =scwin.obj.Provider(scwin.frameId).ActiveFrame; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt76101' }); }

try { scwin.deleteFileArray =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt76101' }); }

try { scwin.deleteFileNameArray =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt76101' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt76101.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt76101.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt76101.btn_mpd_files_del_onclick' }); }
};

