/**
 * @method
 * @name fileTable_oncellclick
 * @description fileTable 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_noticeAttachFiles');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_noticeAttachFiles */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_DeleteFile (인자 미해석) */
        await scwin.fileDownload(r["contnId"], r["contnAttachSeq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'fileTable.oncellclick' });
    }
};

/**
 * @method
