};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Copy
 * @description Copy 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Copy = async function () {
    const sbmOptions = {
        id: "tx_fn_Copy",
        method: "post",
        action: "/filing/updateNotice.do",
        ref: "dma_CopyReq",
        target: "dlt_noticeAttachFiles=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Update
 * @description Update 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Update = async function () {
    const sbmOptions = {
        id: "tx_fn_Update",
        method: "post",
        action: "/filing/updateNotice.do",
        ref: "dma_UpdateReq",
        target: "dlt_noticeAttachFiles=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name copy
 * @description copy 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.copy = async function () {
    await $c.win.alert('복사 등록시 첨부파일은 제외한 내용만 동일하게 등록합니다.');
    scwin.form_copyForm.action = "/filing/updateNotice.do";
    await scwin.tx_fn_Copy();
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    $c.util.getComponent('dma_CopyReq').set('method', "updateNotice");
    scwin.form_editForm.action = "/filing/updateNotice.do";
    if (scwin.deleteFileArray.length > 0) {
        $c.util.getComponent("dma_CopyReq").set("deleteFileArray", scwin.deleteFileArray);
        $c.util.getComponent("dma_CopyReq").set("deleteFileNameArray", scwin.deleteFileNameArray);
    } else {

    }
    let cont = 0;
    for (let i = 0; i < $(".attachFile").length; i++) {
        if ($(".attachFile input").eq(i).prop('value').length !== 0) {
            $(".attachFile input").eq(i).attr('name', 'attachBinfile[' + cont + ']');
            cont++;
        }
    }
    const arrWhiteList = ["hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "gif", "jpg", "jpeg", "bmp", "tif", "txt", "drt", "dsd", "png", "zip", "html"];
    for (let i = 0; i < $(".attachFile").length; i++) {
        const sFileNm = $(".attachFile input").eq(i).prop('value');
        const arrFileNm = sFileNm.split(".");
        const sExtFileNm = arrFileNm[arrFileNm.length-1].toLowerCase().trim();
        let cnt = 0;
        if (sExtFileNm != null && sExtFileNm.length > 0) {
            for (let j = 0; j < arrWhiteList.length; j++) {
                if (sExtFileNm === arrWhiteList[j]) {
                    cnt++;
                }
            }
            if (cnt === 0) {
                await $c.win.alert("[" + sExtFileNm + "] 확장자는 등록할 수 없습니다.");
                return;
            }
        }
    }
    $c.util.getComponent('dma_CopyReq').set('attachFileNum', cont);
    $("#slc_notiObjSysTpCd option").attr('disabled', false);
    if ($c.util.getComponent('slc_notiObjSysTpCd').getValue() === "2" || $c.util.getComponent('slc_notiObjSysTpCd').getValue() === "C") {
        $c.util.getComponent("slc_corpUsrTpCd").setValue("");
        $c.util.getComponent('dma_CopyReq').set('notiTp', $c.util.getComponent('ipt_notiTp1').getValue());
    } else {
        $c.util.getComponent('dma_CopyReq').set('notiTp', $c.util.getComponent('slc_notiTp2').getValue());
    }
    if ($c.util.getComponent('dma_CopyReq').get('notiTp').length !== 1) {
        await $c.win.alert("공지타입을 한자리로 입력하세요.");
        return;
    }
    let startDate = $c.util.getComponent('cal_strtDd').getValue()+ $c.util.getComponent('ipt_strtTm').getValue(); if (startDate == null) { startDate = ''; }
    startDate = startDate.replace(/\-/g, '');
    startDate = startDate.replace(/\:/g, '');
    if (startDate === "") {
        await $c.win.alert("게시 시작일시를 반드시 입력하세요.");
        return;
    }
    if (startDate.length !== 14) {
        await $c.win.alert("게시 시작일시를 형식에 맞게 입력하세요.");
        return;
    }
    let endDate = $c.util.getComponent('cal_endDd').getValue()+ $c.util.getComponent('ipt_endTm').getValue(); if (endDate == null) { endDate = ''; }
    endDate = endDate.replace(/\-/g, '');
    endDate = endDate.replace(/\:/g, '');
    if (endDate === "") {
        await $c.win.alert("게시 종료일시를 반드시 입력하세요.");
        return;
    }
    if (endDate.length !== 14) {
        await $c.win.alert("게시 종료일시를 형식에 맞게 입력하세요.");
        return;
    }
    if (startDate > endDate) {
        await $c.win.alert("시작일은 종료일 이후이여야 합니다.");
        return;
    }
    await scwin.tx_fn_Update();
};

