/**
 * @method
 * @name changeSysTpCd
 * @description change Sys Tp Cd 처리
 * @param {String} sysTpCd sysTpCd
 * @returns {void}
 * @hidden N
 */
scwin.changeSysTpCd = function (sysTpCd) {
    scwin.selectBox(sysTpCd);
    if (sysTpCd === "1" || sysTpCd === "B") {
        ($c.util.getComponent("view_dst1") && $c.util.getComponent("view_dst1").hide ? $c.util.getComponent("view_dst1").hide() : console.warn('[sdd] hide 대상 미해결: ' + "view_dst1"));
        ($c.util.getComponent("view_fil_ods1") && $c.util.getComponent("view_fil_ods1").show ? $c.util.getComponent("view_fil_ods1").show() : console.warn('[sdd] show 대상 미해결: ' + "view_fil_ods1"));
        ($c.util.getComponent("view_dst2") && $c.util.getComponent("view_dst2").hide ? $c.util.getComponent("view_dst2").hide() : console.warn('[sdd] hide 대상 미해결: ' + "view_dst2"));
        ($c.util.getComponent("view_fil_ods2") && $c.util.getComponent("view_fil_ods2").show ? $c.util.getComponent("view_fil_ods2").show() : console.warn('[sdd] show 대상 미해결: ' + "view_fil_ods2"));
    } else {
        ($c.util.getComponent("view_dst1") && $c.util.getComponent("view_dst1").show ? $c.util.getComponent("view_dst1").show() : console.warn('[sdd] show 대상 미해결: ' + "view_dst1"));
        ($c.util.getComponent("view_fil_ods1") && $c.util.getComponent("view_fil_ods1").hide ? $c.util.getComponent("view_fil_ods1").hide() : console.warn('[sdd] hide 대상 미해결: ' + "view_fil_ods1"));
        ($c.util.getComponent("view_dst2") && $c.util.getComponent("view_dst2").show ? $c.util.getComponent("view_dst2").show() : console.warn('[sdd] show 대상 미해결: ' + "view_dst2"));
        ($c.util.getComponent("view_fil_ods2") && $c.util.getComponent("view_fil_ods2").hide ? $c.util.getComponent("view_fil_ods2").hide() : console.warn('[sdd] hide 대상 미해결: ' + "view_fil_ods2"));
    }
};

/**
 * @method
 * @name selectBox
 * @description select Box 처리
 * @param {String} sysTpCd sysTpCd
 * @returns {void}
 * @hidden N
 */
scwin.selectBox = function (sysTpCd) {
    $('select[name=corpUsrTpCd]').find('option').remove();
    $('select[name=corpUsrTpCd]').append("<option value=''>전체</option>");
    if (sysTpCd === "1") {
        for (let i = 0; i < (function(){ throw 'unresolved:list:corpUsrTpCdList1'; })(); i++) {
            $('select[name=corpUsrTpCd]').append("<option value='${corpUsrTpCdList1[__i].cdVal}'" + "${(noticeDetail.corpUsrTpCd == entity.cdVal )?'selected':''} " + ">${corpUsrTpCdList1[__i].cdValNm}</option>");
        }
    } else {
        if (sysTpCd === "B") {
            for (let i1 = 0; i1 < (function(){ throw 'unresolved:list:corpUsrTpCdList2'; })(); i1++) {
                $('select[name=corpUsrTpCd]').append("<option value='${corpUsrTpCdList2[__i1].cdVal}'" + "${(noticeDetail.corpUsrTpCd == entity.cdVal )?'selected':''} " + ">${corpUsrTpCdList2[__i1].cdValNm}</option>");
            }
        }
    }
};

/**
 * @method
 * @name getStringSize
 * @description get String Size 처리
 * @param {*} message message
 * @returns {void}
 * @hidden N
 */
scwin.getStringSize = function (message) {
    let i, len = 0;
    for (i = 0; i < message.length; i++) {
        (message.charCodeAt(i) > 255) ? len += 2 : len++;
    }
    return len;
};

/**
 * @method
 * @name chkByte
