 * @param {Object} obj 컴포넌트
 * @param {*} num num
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkByte = async function (obj, num) {
    await $c.win.alert(num + "바이트까지 입력할 수 있습니다.\n현재" + scwin.getStringSize(obj.value) + "바이트입니다.");
    obj.focus();
};
